  gorsel: null,
  secenekler: ["Afet bölgesine eşya göndermek yasaklanmıştır.", "Yazlık giysiler, depolarda en çok yeri kaplar.", "Listeye bakmak, yardımın ulaşmasını geciktirir.", "Mevsime uymayan giysiler bölgede işe yaramaz."],
